# Writes Bath Navy's hedra command files (every model but the hero duck) and its drawn textures.
# Run from models/env: /usr/bin/python3 make_env.py. Hedra is up Z, front -Y (the GLB comes out Y up,
# front +Z); colours are exact Lost Century hexes, so the bake snaps with error 0. A toy-scale world:
# the tub is 9.2 m long, the duck 1.2 m.
import os
import random

from PIL import Image

HEX = {"tan": "d1b187", "terracotta": "c77b58", "rust": "ae5d40", "maroon": "79444a", "dark": "4b3d44",
       "ochre": "ba9158", "brown": "927441", "olivedark": "4d4539", "olive": "77743b", "mustard": "b3a555",
       "cream": "d2c9a5", "sage": "8caba1", "teal": "4b726e", "plum": "574852", "grey": "847875",
       "silver": "ab9b8e"}


def rgb(name):
    h = HEX[name]
    return tuple(int(h[i:i + 2], 16) for i in (0, 2, 4))


def col(name, emit=False):
    s = "--base-color " + " ".join(f"{c / 255:.4f}" for c in rgb(name))
    return s


def write(name, lines):
    with open(name + ".txt", "w") as f:
        f.write("\n".join(lines) + "\n")


os.makedirs("textures", exist_ok=True)

# ---------------------------------------------------------------- textures (drawn, palette-exact)
# floor: 1.2 m checker tiles, two greys, 0.3 m a texel (4 texels a tile), 48 x 29 over 14.4 x 8.8 m
im = Image.new("RGB", (48, 29))
for y in range(29):
    for x in range(48):
        im.putpixel((x, y), rgb("silver") if ((x // 4) + (y // 4)) % 2 == 0 else rgb("grey"))
im.save("textures/floor.png")
# wall: sage square tiles with teal grout every third texel, 0.25 m a texel, 56 x 20 over 14 x 5 m
im = Image.new("RGB", (56, 20))
for y in range(20):
    for x in range(56):
        im.putpixel((x, y), rgb("teal") if (x % 3 == 2 or y % 3 == 2) else rgb("sage"))
im.save("textures/wall.png")
# bath mat: terracotta with two rust stripes, 12 x 8 over 3 x 2 m
im = Image.new("RGB", (12, 8), rgb("terracotta"))
for x in range(12):
    for y in (2, 5):
        im.putpixel((x, y), rgb("rust"))
im.save("textures/mat.png")
# water: teal with sage ripple dashes (2 x 1 texels and longer), 0.17 m a texel, 50 x 28 over 8.5 x 4.7 m
rnd = random.Random(5)
im = Image.new("RGB", (50, 28), rgb("teal"))
for _ in range(34):
    x, y, n = rnd.randrange(50), rnd.randrange(28), rnd.choice((2, 3, 3, 4))
    for k in range(n):
        im.putpixel(((x + k) % 50, y), rgb("sage"))
im.save("textures/water.png")

